// === OPPOSITE-ENDS TWO POINTERS (sorted array) ===
function oppositeTwoPointers(arr, target) {
  let left = 0, right = arr.length - 1;
  while (left < right) {
    const val = arr[left] + arr[right]; // or any pair evaluation
    if (val === target) {
      return [left, right];
    } else if (val < target) {
      left++;   // current left too small, move right to increase
    } else {
      right--;  // current right too large, move left to decrease
    }
  }
  return [];
}

// === FAST/SLOW POINTERS ===
function fastSlowPointers(head) {
  let slow = head, fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;        // one step
    fast = fast.next.next;   // two steps
    if (slow === fast) return true; // cycle detected
  }
  return false; // fast reached end: no cycle
}
